protected findNearestItem(context: yfiles.IInputModeContext, startLocation: yfiles.Point, direction: yfiles.MoveFocusDirection, itemsToCheck: yfiles.IEnumerable<yfiles.IModelItem>): yfiles.IModelItem | null;
