/**
Used by {@link yfiles.CreateEdgeInputMode} to determine the {@link yfiles.EdgeDirectionPolicy direction} in which edges get created.
@final*/
export enum EdgeDirectionPolicy {
/**
The default policy where edges can only be created from source to target port.*/
START_AT_SOURCE,
/**
A policy where edges can only be created from target to source port in {@link yfiles.CreateEdgeInputMode.reversedEdgeCreation reverse} direction.*/
START_AT_TARGET,
/**
A policy where edges will be created in the same direction as last time.*/
KEEP_DIRECTION,
/**
* A policy where edges will be created in the direction depending on whether the creation started at a {@link yfiles.IPortCandidateProvider.getAllSourcePortCandidates source} or {@link yfiles.IPortCandidateProvider.getAllTargetPortCandidates target}
* {@link yfiles.IPortCandidate}.
* With this policy {@link yfiles.CreateEdgeInputMode} queries both {@link yfiles.IPortCandidateProvider.getAllSourcePortCandidates}
* and {@link yfiles.IPortCandidateProvider.getAllTargetPortCandidates} for a port candidate to start edge creation from. If
* the chosen candidate has been returned by the latter method the edge will be created in reversed order.
*
* This requires a custom IPortCandidateProvider which implements both {@link yfiles.IPortCandidateProvider.getAllSourcePortCandidates}
* and {@link yfiles.IPortCandidateProvider.getAllTargetPortCandidates} to return candidates to start edge creation at the
* source port and at the target port, respectively.
* ```
* public class TagSensitivePortCandidateProvider : IPortCandidateProvider
* {
*   private readonly IPortOwner owner;
*
*
*   public TagSensitivePortCandidateProvider(IPortOwner owner) {
*     this.owner = owner;
*   }
*
*
*   public IEnumerable<IPortCandidate> GetSourcePortCandidates(IInputModeContext context) {
*     return from port in owner.Ports where "Source".Equals(port.Tag) select new DefaultPortCandidate(port);
*   }
*
*
*   public IEnumerable<IPortCandidate> GetTargetPortCandidates(IInputModeContext context) {
*     return from port in owner.Ports where "Target".Equals(port.Tag) select new DefaultPortCandidate(port);
*   }
*
*
*   ...
*
*
* }
* ```
*
* [Read this documentation with sample code online](https://docs.yworks.com/yfileshtml/#/api/EdgeDirectionPolicy%23DETERMINE_FROM_PORT_CANDIDATES).
*/
DETERMINE_FROM_PORT_CANDIDATES
}
