protected onCopy(sourceGraph: yfiles.IGraph, filter: (obj: yfiles.IModelItem) => boolean, targetGraph: yfiles.IGraph, targetRootNode: yfiles.INode | null, elementCopiedCallback: ((original: yfiles.IModelItem, copy: yfiles.IModelItem) => void) | null): void;
