styleBindings?: yfiles.ObjectBindings<TDataItem> | yfiles.ObjectBindingsConvertible<TDataItem>;
/**
An optional provider of an {@link yfiles.INodeStyle} instance that will be used as the node's {@link yfiles.INode.style} for the source data item. This option sets the {@link yfiles.NodeCreator.styleProvider} property on the created object.*/
style?: ((dataItem: TDataItem) => yfiles.INodeStyle | null | undefined) | null | yfiles.ProviderConvertible<TDataItem, yfiles.INodeStyle>;
